import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { FaHome, FaPlus, FaPaintBrush, FaBars } from "react-icons/fa";

const Sidebar = () => {
  const [collapsed, setCollapsed] = useState(false);
  const navigate = useNavigate();

  return (
    <div style={{ ...styles.sidebar, width: collapsed ? "80px" : "250px" }}>
      {/* Header row: collapse toggle in normal flow (NOT absolute) so it never
          sits underneath any other control. */}
      <div style={styles.headerRow}>
        <button
          onClick={() => setCollapsed(!collapsed)}
          style={styles.toggleButton}
          title={collapsed ? "Expand menu" : "Collapse menu"}
        >
          <FaBars />
        </button>
      </div>

      {/* Logo */}
      <div style={styles.logo}>
        <FaPaintBrush size={26} color="#005a91" />
        {!collapsed && (
          <span style={styles.logoText}>PF Design Studio</span>
        )}
      </div>

      {/* Plain anchor to the portal root (same origin). NOT a router route:
          basename is /design-studio so navigate("/") would stay in the studio.
          href="/" returns the current tab to the main portal; single login
          already applies, no second prompt. In-flow header control, visible on
          both Home and the editor, never overlapping the toggle or canvas tools. */}
      <a href="/" style={styles.backToPortal} title="Back to Portal">
        <FaHome />
        {!collapsed && <span>Back to Portal</span>}
      </a>

      {/* Sidebar Menu */}
      <ul style={styles.list}>
        {menuItems.map((item, index) => (
          <li 
            key={index} 
            style={styles.item} 
            onClick={() => navigate(item.path)}
            onMouseEnter={(e) => e.currentTarget.style.background = "rgba(0, 0, 0, 0.1)"}
            onMouseLeave={(e) => e.currentTarget.style.background = "transparent"}
          >
            {item.icon}
            {!collapsed && <span>{item.label}</span>}
          </li>
        ))}
      </ul>
    </div>
  );
};

const styles = {
  sidebar: {
    height: "100vh",
    width: "250px",  // Fixed width
    backgroundColor: "rgba(255, 255, 255, 0.6)",
    backdropFilter: "blur(10px)",
    color: "#000",
    padding: "20px",
    boxSizing: "border-box",
    transition: "width 0.3s ease",
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    position: "fixed",  // Keeps sidebar fixed on the left
    left: 0,
    top: 0,
    bottom: 0,
    borderRight: "1px solid rgba(0, 0, 0, 0.1)",
    overflow: "hidden", // Prevents extra spacing issues
  },
  headerRow: {
    width: "100%",
    display: "flex",
    justifyContent: "flex-start",
    marginBottom: "8px",
  },
  toggleButton: {
    background: "#333",
    border: "none",
    color: "white",
    fontSize: "18px",
    padding: "8px 10px",
    borderRadius: "5px",
    cursor: "pointer",
    transition: "background 0.3s ease",
  },
  logo: {
    display: "flex",
    alignItems: "center",
    fontSize: "24px",
    fontWeight: "bold",
    marginBottom: "20px",
    marginTop: "8px",
    gap: "10px",
  },
  logoText: {
    display: "flex",
    gap: "2px",
    fontWeight: "bold",
    fontSize: "17px",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
    letterSpacing: "0.2px",
    color: "#0b2b3c",
    whiteSpace: "nowrap",
  },
  list: {
    listStyle: "none",
    padding: 0,
    width: "100%",
  },
  item: {
    display: "flex",
    alignItems: "center",
    gap: "10px",
    padding: "12px",
    cursor: "pointer",
    borderRadius: "5px",
    transition: "background 0.3s",
    color: "#333",
    fontSize: "16px",
    fontWeight: "500",
  },
  backToPortal: {
    marginBottom: "16px",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    gap: "8px",
    width: "100%",
    padding: "12px",
    boxSizing: "border-box",
    background: "#005a91",
    color: "#fff",
    textDecoration: "none",
    borderRadius: "6px",
    fontSize: "15px",
    fontWeight: 600,
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
  },
};

// Only routes that actually exist in App.js. The original Projects/Templates/
// Settings links pointed at non-existent routes (backend-backed in the source
// project) and rendered a blank page, so they are removed.
const menuItems = [
  { icon: <FaHome />, label: "Home", path: "/" },
  { icon: <FaPlus />, label: "Create Design", path: "/editor" },
];

export default Sidebar;
